-- Exam module (exam.db)
-- Recruitment exams, questions, attempts and answers.
-- Generated by Migrations/build_module_databases.py --refresh-schema;
-- foreign keys into another module's file are dropped on purpose.

CREATE TABLE recruitment_exams (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        vacancy_id INTEGER NOT NULL,
        exam_title TEXT NOT NULL,
        description TEXT DEFAULT '',
        duration_minutes INTEGER NOT NULL DEFAULT 60 CHECK (duration_minutes > 0),
        total_marks REAL NOT NULL DEFAULT 100 CHECK (total_marks > 0),
        pass_mark REAL NOT NULL DEFAULT 50 CHECK (pass_mark >= 0),
        start_datetime TEXT,
        end_datetime TEXT,
        status TEXT NOT NULL DEFAULT 'Draft' CHECK (status IN ('Draft', 'Published', 'Closed')),
        created_by_id INTEGER,
        created_by_name TEXT DEFAULT '',
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_by INTEGER, updated_by_name TEXT, updated_at TEXT);

CREATE TABLE exam_questions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        exam_id INTEGER NOT NULL,
        question TEXT NOT NULL,
        option_a TEXT NOT NULL DEFAULT '',
        option_b TEXT NOT NULL DEFAULT '',
        option_c TEXT NOT NULL DEFAULT '',
        option_d TEXT NOT NULL DEFAULT '',
        correct_answer TEXT NOT NULL DEFAULT 'A' CHECK (correct_answer IN ('A', 'B', 'C', 'D')),
        marks REAL NOT NULL DEFAULT 1 CHECK (marks > 0),
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (exam_id) REFERENCES recruitment_exams(id) ON DELETE CASCADE
    );

CREATE TABLE exam_attempts (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        exam_id INTEGER NOT NULL,
        application_id INTEGER NOT NULL,
        started_at TEXT,
        submitted_at TEXT,
        score REAL NOT NULL DEFAULT 0,
        status TEXT NOT NULL DEFAULT 'Not Started' CHECK (status IN ('Not Started', 'In Progress', 'Submitted', 'Missed')),
        access_token_hash TEXT,
        token_created_at TEXT,
        FOREIGN KEY (exam_id) REFERENCES recruitment_exams(id) ON DELETE CASCADE,
        UNIQUE (exam_id, application_id)
    );

CREATE TABLE exam_answers (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        attempt_id INTEGER NOT NULL,
        question_id INTEGER NOT NULL,
        selected_answer TEXT NOT NULL DEFAULT '',
        marks_awarded REAL NOT NULL DEFAULT 0,
        FOREIGN KEY (attempt_id) REFERENCES exam_attempts(id) ON DELETE CASCADE,
        FOREIGN KEY (question_id) REFERENCES exam_questions(id) ON DELETE CASCADE,
        UNIQUE (attempt_id, question_id)
    );

CREATE UNIQUE INDEX idx_attempt_token ON exam_attempts (access_token_hash) WHERE access_token_hash IS NOT NULL;
